import React, { useState } from 'react';
import UserList from './presentational-component';

function ContainerComponent() {
  const [users] = useState([
    { id: 1, name: 'Rahul' },
    { id: 2, name: 'Priya' },
    { id: 3, name: 'Amit' }
  ]);


  return <UserList users={users} />;
}

export default ContainerComponent;
